                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
        );

        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());

        int successCount = 0;
        int errorCount = 0;

